{"valorTotalHomologado":850.0,"orgaoEntidade":{"cnpj":"26994533000120","razaoSocial":"ADMINISTRACAO REGIONAL DE BRASILIA","poderId":"E","esferaId":"D"},"dataInclusao":"2026-03-12T14:14:41","dataAtualizacao":"2026-03-12T14:14:41","emendaParlamentar":null,"numeroCompra":"2","processo":"00141-00000922/2026-41","objetoCompra":"contratação de empresa especializada para fornecimento de solução de telefonia baseada em tecnologia Voice over Internet Protocol (VoIP), utilizando sistema de PABX em nuvem (Cloud PBX), destinada ao atendimento das necessidades da Administração Regional do Plano Piloto – RA-PP.","informacaoComplementar":"A solução deverá contemplar, no mínimo:
I- disponibilização de 34 (trinta e quatro) ramais de telefonia IP;
II- fornecimento de aparelhos telefônicos IP físicos para todos os ramais, em regime de comodato, incluindo instalação, configuração e suporte técnico;
III- disponibilização de sistema PABX em nuvem (Cloud PBX) com gerenciamento centralizado da solução;
IV- ligações ilimitadas para telefones fixos e móveis em todo o território nacional, sem limitação de minutos;
V- implantação da solução, incluindo instalação, configuração e testes de funcionamento;
VI- portabilidade numérica, preferencialmente mantendo os números atualmente utilizados pela Administração, observadas as regras da Agência Nacional de Telecomunicações – ANATEL;
VII- disponibilização de URA – Unidade de Resposta Audível (atendimento eletrônico) para direcionamento automatizado de chamadas;
VIII- fornecimento de portal web de administração da solução, permitindo gestão de ramais, relatórios e monitoramento das chamadas;
IX- suporte técnico, manutenção preventiva e corretiva, atualizações da solução e garantia de funcionamento durante toda a vigência contratual.
X- disponibilização de funcionalidade de gravação de chamadas, de forma opcional, podendo ser habilitada para os ramais definidos pela Administração, com acesso aos registros por meio de portal web de gerenciamento.","dataAberturaProposta":"2026-03-13T08:00:00","dataEncerramentoProposta":"2026-03-20T08:00:00","dataPublicacaoPncp":"2026-03-12T14:14:41","dataAtualizacaoGlobal":"2026-03-27T15:30:32","unidadeOrgao":{"ufNome":"Distrito Federal","ufSigla":"DF","municipioNome":"Brasília","codigoUnidade":"932081","nomeUnidade":"EDF-ADMINISTRAÇÃO REGIONAL DO PLANO PILOTO","codigoIbge":"5300108"},"orgaoSubRogado":null,"unidadeSubRogada":null,"amparoLegal":{"nome":"Lei 14.133/2021, Art. 75, II","descricao":"Dispensa de Licitação: para contratação que envolva valores inferiores a R$ 50.000,00 (cinquenta mil reais), no caso de outros serviços e compras","codigo":19},"linkSistemaOrigem":null,"linkProcessoEletronico":"http://sei.df.gov.br/sei/controlador.php?acao=procedimento_trabalhar&id_procedimento=216471676","justificativaPresencial":null,"numeroControlePNCP":"26994533000120-1-000002/2026","anoCompra":2026,"srp":false,"sequencialCompra":2,"valorTotalEstimado":2040.0,"modalidadeId":8,"modalidadeNome":"Dispensa","modoDisputaId":4,"modoDisputaNome":"Dispensa Com Disputa","tipoInstrumentoConvocatorioCodigo":2,"tipoInstrumentoConvocatorioNome":"Aviso de Contratação Direta","fontesOrcamentarias":[],"situacaoCompraId":1,"situacaoCompraNome":"Divulgada no PNCP","usuarioNome":"Compras.gov.br"}

