{"valorTotalHomologado":2062500.0,"orgaoEntidade":{"cnpj":"04384829000196","poderId":"E","razaoSocial":"FUNDO ESTADUAL DE SAUDE","esferaId":"E"},"dataInclusao":"2026-03-12T09:48:39","dataAtualizacao":"2026-04-08T16:58:59","numeroControlePNCP":"04384829000196-1-000095/2026","anoCompra":2026,"srp":false,"sequencialCompra":95,"emendaParlamentar":null,"numeroCompra":"IN0012","processo":"IN0012/2026","objetoCompra":"CREDENCIAMENTO PARA FORMAÇÃO DO CADASTRO ESTADUAL DE PRESTADORES PRIVADOS INTERESSADOS EM PRESTAR SERVIÇOS DE SAÚDE PARA O ACOLHIMENTO PEDIÁTRICO DE URGÊNCIA EM AMBIENTE HOSPITALAR E INTERNAÇÃO PEDIÁTRICA PARA O PERÍODO DE SAZONALIDADE DAS SÍNDROMES RESPIRATÓRIAS AGUDAS GRAVES E DAS ARBOVIROSES","informacaoComplementar":"A CONSTITUIÇÃO FEDERAL, EM SEU ART. 196, ESTABELECE QUE A SAÚDE É DIREITO DE TODOS E DEVER DO ESTADO, GARANTIDO MEDIANTE POLÍTICAS SOCIAIS E ECONÔMICAS QUE VISEM À REDUÇÃO DO RISCO DE DOENÇA E AO ACESSO UNIVERSAL E IGUALITÁRIO ÀS AÇÕES E SERVIÇOS PARA SUA PROMOÇÃO, PROTEÇÃO E RECUPERAÇÃO.
NESSE CONTEXTO, INCUMBE AO ESTADO ADOTAR MEDIDAS PREVENTIVAS E ESTRUTURANTES QUE ASSEGUREM A CONTINUIDADE E A INTEGRALIDADE DA ASSISTÊNCIA, ESPECIALMENTE EM PERÍODOS DE MAIOR VULNERABILIDADE SANITÁRIA.
NOS TERMOS DA LEI Nº 14.133/2021, O PLANEJAMENTO É ETAPA OBRIGATÓRIA DA CONTRATAÇÃO PÚBLICA, DEVENDO A ADMINISTRAÇÃO DEMONSTRAR A NECESSIDADE DA CONTRATAÇÃO, SUA ADEQUAÇÃO AO INTERESSE PÚBLICO E A COMPATIBILIDADE COM O PLANEJAMENTO INSTITUCIONAL. A MEDIDA TAMBÉM OBSERVA AS DISPOSIÇÕES DO DECRETO ESTADUAL Nº 342/2023, QUANTO À FORMALIZAÇÃO, MOTIVAÇÃO E ESTIMATIVA DA DEMANDA.
ASSIM SENDO, CONSIDERANDO QUE A SECRETARIA DE ESTADO DA SAÚDE DE SERGIPE POSSUI ABERTO O EDITAL DE CREDENCIAMENTO DE Nº 03/2024 QUE VISA A FORMAÇÃO DO “CADASTRO ESTADUAL DE PRESTADORES PRIVADOS INTERESSADOS EM PRESTAR SERVIÇOS DE SAÚDE PARA O ACOLHIMENTO PEDIÁTRICO DE URGÊNCIA EM AMBIENTE HOSPITALAR E INTERNAÇÃO PEDIÁTRICA PARA O PERÍODO DE SAZONALIDADE DAS SÍNDROMES RESPIRATÓRIAS AGUDAS GRAVES E DAS ARBOVIROSES.”
CONSIDERANDO QUE OS DADOS DO SIH EVIDENCIAM AUMENTO RELEVANTE DE INTERNAÇÕES PEDIÁTRICAS POR DOENÇAS RESPIRATÓRIAS NO PERÍODO SAZONAL DE 2025, COM REPERCUSSÃO DIRETA NA OCUPAÇÃO DE LEITOS DE UTIP E SEMI-INTENSIVA;
CONSIDERANDO QUE A INSUFICIÊNCIA DE LEITOS CRÍTICOS PODE OCASIONAR ATRASO NA ADMISSÃO DE PACIENTES GRAVES; TRANSFERÊNCIAS INTERESTADUAIS OU DESLOCAMENTOS PROLONGADOS; RISCO DE AGRAVAMENTO CLÍNICO POR DEMORA NA ASSISTÊNCIA INTENSIVA; SOBRECARGA DAS EQUIPES E COMPROMETIMENTO DA QUALIDADE ASSISTENCIAL. 
CONSIDERANDO QUE A CONTRATAÇÃO TEMPORÁRIA DE LEITOS ADICIONAIS PERMITE ADEQUAR A CAPACIDADE INSTALADA À DEMANDA EPIDEMIOLÓGICA; REDUZIR RISCOS ASSISTENCIAIS; PRESERVAR A SEGURANÇA DO PACIENTE; EVITAR COLAPSO DA REDE HOSPITALAR ESTADUAL; GARANTIR RESPOSTA RÁPIDA E PROPORCIONAL AO AUMENTO SAZONAL DE CASOS.
A AMPLIAÇÃO TEMPORÁRIA DA OFERTA MOSTRA-SE MAIS EFICIENTE E ECONOMICAMENTE RACIONAL DO QUE A AMPLIAÇÃO ESTRUTURAL PERMANENTE DA REDE, CONSIDERANDO O CARÁTER SAZONAL DA DEMANDA;
CONSIDERANDO QUE A CONTRATUALIZAÇÃO POR MEIO DO CREDENCIAMENTO JÁ EXISTENTE CONFERE MAIOR CELERIDADE AO PROCESSO, ASSEGURANDO RESPOSTA TEMPESTIVA ANTES DO PICO EPIDEMIOLÓGICO PREVISTO;
CONSIDERANDO QUE A MEDIDA ATENDE AOS PRINCÍPIOS DA LEGALIDADE, EFICIÊNCIA, CONTINUIDADE DO SERVIÇO PÚBLICO, PLANEJAMENTO E SUPREMACIA DO INTERESSE PÚBLICO;
CONSIDERANDO QUE A PRETENDIDA CONTRATUALIZAÇÃO OBJETIVA ASSEGURAR A ASSISTÊNCIA ADEQUADA E OPORTUNA AOS PACIENTES PEDIÁTRICOS DEVIDO À MAIOR INCIDÊNCIA DE DOENÇAS RESPIRATÓRIAS, COMO BRONQUIOLITE, PNEUMONIA, INFLUENZA E OUTRAS INFECÇÕES VIRAIS, BEM COMO SURTOS DE GASTROENTERITES E DOENÇAS EXANTEMÁTICAS. ESSES FATORES RESULTAM EM UM MAIOR NÚMERO DE INTERNAÇÕES, SOBRECARREGANDO A ESTRUTURA HOSPITALAR EXISTENTE;
CONSIDERANDO QUE O PERÍODO DE SAZONALIDADE APRESENTA UM AUMENTO DE CASOS RELACIONADOS À SÍNDROME RESPIRATÓRIA AGUDA GRAVE (SRAG), PRINCIPALMENTE EM CRIANÇAS, CAUSANDO UM IMPACTO SIGNIFICATIVO NA OCUPAÇÃO DE LEITOS DE UTIP E SEMI-INTENSIVA; 
CONSIDERANDO QUE DIANTE DO CENÁRIO ACIMA DESCRITO, CONFORME DEMONSTRADO NOS GRÁFICOS EXTRAÍDOS DA SIH, TORNA-SE IMPRESCINDÍVEL A AMPLIAÇÃO DA OFERTA DE LEITOS PEDIÁTRICOS PARA GARANTIR ASSISTÊNCIA ADEQUADA, JÁ QUE CONTRATAÇÃO TEMPORÁRIA DE LEITOS ADICIONAIS PERMITE ADEQUAR A OFERTA À DEMANDA, EVITANDO COLAPSOS NA REDE HOSPITALAR.
TRATA-SE, PORTANTO, DE MEDIDA PREVENTIVA, PLANEJADA E ALINHADA ÀS DIRETRIZES DE REGIONALIZAÇÃO E HIERARQUIZAÇÃO DO SUS.
DIANTE DO EXPOSTO, SOLICITAMOS A CONTRATAÇÃO DE SERVIÇOS DE SAÚDE, COM FOCO NA ASSISTÊNCIA EM PEDIATRIA, ATRAVÉS DA DISPONIBILIZAÇÃO DE LEITOS DE UTI PEDIÁTRICA E SEMIINTENSIVA PELA CONTRATADA (COMPREENDENDO: ESTRUTURA FÍSICA, RECURSOS HUMANOS, MOBILIÁRIOS, EQUIPAMENTOS, MATERIAIS E INSUMOS) DEFININDO SUA INSERÇÃO NA REDE REGIONALIZADA E HIERARQUIZADA DE AÇÕES E SERVIÇOS DE SAÚDE DE FORMA TEMPORÁRIA.","dataAberturaProposta":null,"dataEncerramentoProposta":null,"dataPublicacaoPncp":"2026-03-12T09:48:39","dataAtualizacaoGlobal":"2026-04-08T16:59:07","unidadeOrgao":{"ufNome":"Sergipe","ufSigla":"SE","municipioNome":"Aracaju","codigoIbge":"2800308","nomeUnidade":"SECRETARIA DE ESTADO DA SAÚDE","codigoUnidade":"04384829000196"},"orgaoSubRogado":null,"unidadeSubRogada":null,"amparoLegal":{"nome":"Lei 14.133/2021, Art. 74, IV","descricao":"Inexigibilidade de Licitação: objetos que devam ou possam ser contratados por meio de credenciamento","codigo":16},"linkSistemaOrigem":"https://sistema.comprasnet.se.gov.br/publico/WKF.aspx?code=SES-IN0012/2026&validation=50966","linkProcessoEletronico":null,"justificativaPresencial":null,"valorTotalEstimado":2062500.0,"modalidadeId":9,"modalidadeNome":"Inexigibilidade","modoDisputaId":5,"modoDisputaNome":"Não se aplica","tipoInstrumentoConvocatorioCodigo":3,"tipoInstrumentoConvocatorioNome":"Ato que autoriza a Contratação Direta","fontesOrcamentarias":[],"situacaoCompraId":1,"situacaoCompraNome":"Divulgada no PNCP","usuarioNome":"ASJB Consultoria S/C Ltda"}

