{"valorTotalHomologado":324800.0,"orgaoEntidade":{"cnpj":"32001836000105","razaoSocial":"MUNICIPIO DE SAO JOSE DO VALE DO RIO PRETO","poderId":"E","esferaId":"M"},"dataInclusao":"2026-09-09T14:57:10","dataAtualizacao":"2026-09-09T14:57:10","emendaParlamentar":null,"numeroCompra":"9288","processo":"9288","objetoCompra":"Adesão de Veículo","informacaoComplementar":"","dataAberturaProposta":"2026-09-09T12:50:00","dataEncerramentoProposta":"2026-09-09T13:00:00","dataPublicacaoPncp":"2026-09-09T14:57:10","dataAtualizacaoGlobal":"2026-09-09T14:57:18","unidadeOrgao":{"ufNome":"Rio de Janeiro","ufSigla":"RJ","municipioNome":"São José do Vale do Rio Preto","codigoUnidade":"1","nomeUnidade":"PREFEITURA MUNICIPAL DE SÃO JOSÉ DO VALE DO RIO PRETO - RJ","codigoIbge":"3305158"},"orgaoSubRogado":null,"unidadeSubRogada":null,"amparoLegal":{"nome":"Lei 14.133/2021, Art. 28, I","descricao":"pregão: modalidade de licitação obrigatória para aquisição de bens e serviços comuns","codigo":1},"linkSistemaOrigem":"https://www.sjvriopreto.rj.gov.br/uploads/diariooficial/54991/28_08.pdf","linkProcessoEletronico":null,"justificativaPresencial":"A Secretaria Municipal desenvolve diversas atividades externas voltadas ao atendimento das famílias em
situação de vulnerabilidade social, especialmente por meio do Serviço de Convivência e Fortalecimento de
Vínculos, que promove oficinas, atividades culturais, esportivas, recreativas, educativas e comunitárias
destinadas a crianças, adolescentes, adultos e idosos.
O Município possui atualmente uma Van utilizada para o transporte dos usuários dos serviços
socioassistenciais. Entretanto, o veículo apresenta elevado tempo de utilização, desgaste decorrente dos anos
de uso e necessidade constante de manutenção corretiva, ocasionando indisponibilidade frequente e aumento
dos custos de conservação.
A continuidade dessa situação compromete a regularidade dos serviços ofertados, podendo ocasionar
cancelamento ou adiamento de atividades coletivas, dificuldades logísticas para deslocamento dos usuários e
prejuízo ao atendimento da população.
Dessa forma, mostra-se necessária a substituição do veículo atualmente utilizado por uma Van nova,
garantindo maior segurança, confiabilidade, conforto, eficiência operacional e redução dos custos de
manutenção.
O veículo será utilizado para:
• transporte dos usuários do Serviço de Convivência e Fortalecimento de Vínculos;
• deslocamento de grupos do CRAS;
• participação em eventos, encontros e atividades intermunicipais;
• visitas coletivas e ações comunitárias;
• atividades intersetoriais desenvolvidas em parceria com outras Secretarias;
• campanhas socioassistenciais;
• atividades externas promovidas pela Proteção Social Básica;
• transporte das equipes técnicas quando necessário para execução das ações institucionais","numeroControlePNCP":"32001836000105-1-000212/2026","anoCompra":2026,"srp":true,"sequencialCompra":212,"valorTotalEstimado":324800.0,"modalidadeId":7,"modalidadeNome":"Pregão - Presencial","modoDisputaId":2,"modoDisputaNome":"Fechado","tipoInstrumentoConvocatorioCodigo":1,"tipoInstrumentoConvocatorioNome":"Edital","fontesOrcamentarias":[],"situacaoCompraId":1,"situacaoCompraNome":"Divulgada no PNCP","usuarioNome":"Fiorilli Software"}

