{"valorTotalHomologado":null,"orgaoEntidade":{"cnpj":"82939398000190","razaoSocial":"MUNICIPIO DE AGUA DOCE","poderId":"N","esferaId":"M"},"dataAtualizacao":"2026-11-17T14:31:33","dataInclusao":"2026-11-17T14:31:33","unidadeSubRogada":null,"emendaParlamentar":null,"anoCompra":2026,"srp":false,"dataAtualizacaoGlobal":"2026-11-17T14:31:36","linkProcessoEletronico":null,"justificativaPresencial":"A contratação justifica-se pela necessidade de disponibilizar às Secretarias e setores da Administração Municipal acesso periódico a informações e notícias de interesse público, especialmente aquelas relacionadas ao município de Água Doce e à região, possibilitando o acompanhamento de acontecimentos, fatos e conteúdos relevantes às atividades institucionais e à comunidade.

O Jornal Expresso possui circulação semanal e constitui, atualmente, o único jornal impresso de circulação regular na sede do município de Água Doce, contemplando em suas edições notícias e informações de âmbito local e regional. Essa característica possibilita o acompanhamento de conteúdos diretamente relacionados à realidade do Município e de interesse da Administração Pública.

Dessa forma, pretende-se contratar 09 (nove) assinaturas do Jornal Expresso, pelo período de 12 (doze) meses, destinadas às Secretarias e setores da Administração Municipal, garantindo o acesso regular ao conteúdo jornalístico e informativo.","processo":"102/2026","numeroCompra":"DL 13","linkSistemaOrigem":"","informacaoComplementar":"","objetoCompra":"Contratação de empresa para fornecimento de 09 (nove) assinaturas de jornal impresso, com entrega mensal, pelo período de 12 (doze) meses, destinadas ao atendimento das necessidades das Secretarias e setores da Administração Municipal de Água Doce/SC, solicitado através do Documento de Formalização de Demanda nº. 029/2026.","orgaoSubRogado":null,"numeroControlePNCP":"82939398000190-1-000126/2026","unidadeOrgao":{"ufNome":"Santa Catarina","ufSigla":"SC","municipioNome":"Água Doce","codigoUnidade":"2742","nomeUnidade":"Prefeitura de Água Doce","codigoIbge":"4200408"},"dataPublicacaoPncp":"2026-11-17T14:31:33","sequencialCompra":126,"dataEncerramentoProposta":null,"dataAberturaProposta":null,"amparoLegal":{"nome":"Lei 14.133/2021, Art. 75, II","descricao":"Dispensa de Licitação: para contratação que envolva valores inferiores a R$ 50.000,00 (cinquenta mil reais), no caso de outros serviços e compras","codigo":19},"valorTotalEstimado":3600.0,"modalidadeId":8,"modalidadeNome":"Dispensa","modoDisputaId":5,"modoDisputaNome":"Não se aplica","tipoInstrumentoConvocatorioCodigo":3,"tipoInstrumentoConvocatorioNome":"Ato que autoriza a Contratação Direta","fontesOrcamentarias":[],"situacaoCompraId":1,"situacaoCompraNome":"Divulgada no PNCP","usuarioNome":"Betha Sistemas"}

